let deviceDatabase=null,deviceWriter=null,deviceTimer=null,deviceDirty=false,deviceVersion=0,deviceError='',deviceEnding=false;
function renderSaveStatus(){const failed=dirty||!!deviceError||!!toolsError;$('storageWarning').hidden=!failed;$('storageWarning').querySelector('span').textContent=toolsError||deviceError||'This tab could not be saved. Export a backup before leaving.';$('saveState').textContent=failed?'Save problem — export a backup':deviceDirty?'Saving on this device…':'Saved on this device';$('deviceStatus').textContent=deviceError?'Device save unavailable':deviceDirty?'Saving…':'Saved on this browser';if($('designSaveStatus'))$('designSaveStatus').textContent=$('saveState').textContent;if($('designBackup'))$('designBackup').hidden=!failed}
function scheduleDeviceSave(){if(deviceEnding)return;if(!deviceWriter){deviceError||='Device storage is unavailable. Export a backup before closing.';return}deviceDirty=true;deviceVersion++;clearTimeout(deviceTimer);deviceTimer=setTimeout(()=>flushDeviceSave().catch(()=>{}),300)}
async function flushDeviceSave(){clearTimeout(deviceTimer);if(deviceEnding||!deviceDirty)return;if(!deviceWriter)throw Error(deviceError||'Device storage is unavailable.');return deviceSaveDrain.flush()}

async function saveWorkspaceNow(){try{checkpoint();save();await flushDeviceSave();await flushRecovery();if(dirty||deviceDirty||deviceError||recoveryDirty||toolsPending||toolsError)throw Error(toolsError||deviceError||'Some changes still need saving. Check App status or export a backup.');toast('Workspace saved on this device.')}catch(error){toast(error.message)}}
function showDeviceStorage(){modal('Device storage','<p>Documents save automatically on this browser, even with encrypted recovery off. Each workspace has a random local token, not a hardware device ID. No app account is required. Closing and reopening restores saved work. Anyone using this browser profile can open ordinary saved documents. Use End session to remove this workspace on shared devices.</p><button class="wide" id="saveDeviceNow">Save on device now</button><button class="wide primary" id="requestDevicePersistence">Allow persistent device storage</button><p id="persistenceStatus" role="status">Checking storage permission…</p><p>The browser may show a permission prompt or decide automatically. If permission is declined, saving still works but the browser may evict data. Clearing site data removes saved work regardless of permission. Keep exported backups.</p><h3>Workspace capacity</h3><p id="workspaceCapacity"></p><p id="storageCapacityEstimate" role="status">Checking available storage…</p><button id="refreshStorageCapacity" class="wide">Refresh capacity</button><h3>Saved workspaces on this browser</h3><div id="savedWorkspaces">Loading…</div>');const workspaceId=state.id;async function refreshCapacity(){if(workspaceId!==state.id)return;const stats=workspaceUsage(state);$('workspaceCapacity').textContent=`${stats.documents} of ${stats.documentLimit} documents · ${stats.deleted} deleted · ${stats.historyEntries} history entries · ${(stats.bytes/1048576).toFixed(1)} MB of text, embedded images and history.`+(tabCache.reduced?' Tab cache is reduced; committed work reopens from device storage.':'');const output=$('storageCapacityEstimate');try{const estimate=formatStorageEstimate(await navigator.storage?.estimate?.());if(!output.isConnected||workspaceId!==state.id)return;output.textContent=estimate?`${estimate.usedMB} MB used of approximately ${estimate.quotaMB} MB for this site (${estimate.percent}%). `+(estimate.nearLimit?'Storage is nearly full. Export backups and remove unused files or workspaces.':'This includes offline components and saved document tools. Browser capacity can change.'):'The browser does not provide a storage-capacity estimate.'}catch{if(output.isConnected)output.textContent='Storage capacity could not be checked.'}}action('refreshStorageCapacity',refreshCapacity);refreshCapacity();const output=$('persistenceStatus');navigator.storage?.persisted?.().then(granted=>{if(output.isConnected)output.textContent=granted?'Persistent storage is allowed.':'Persistent storage has not been granted.'}).catch(()=>{if(output.isConnected)output.textContent='Permission status is unavailable.'});if(!navigator.storage?.persist)output.textContent='Persistent storage permission is unavailable in this browser context.';action('saveDeviceNow',async()=>{try{deviceDirty=true;await flushDeviceSave();toast('Workspace saved on this device.')}catch(error){toast(error.message)}});action('requestDevicePersistence',async()=>{const result=await requestPersistence(navigator.storage);if(output.isConnected)output.textContent={granted:'Persistent storage allowed. Manual clearing still removes saved work.',denied:'The browser did not grant persistent storage. Device saving remains available.',unavailable:'Persistent storage permission is unavailable.'}[result]});const list=$('savedWorkspaces');deviceDatabase?.summaries().then(records=>{if(!list.isConnected)return;list.replaceChildren();for(const record of records){const button=document.createElement('button');button.className='wide';const titles=record.titles;button.textContent=titles.slice(0,2).join(' · ')+(record.documentCount>2?' +'+(record.documentCount-2):'');button.setAttribute('aria-label','Open workspace: '+button.textContent);button.disabled=record.id===state.id;button.onclick=()=>openDeviceWorkspace(record.id);const small=document.createElement('small');small.textContent=record.id===state.id?'Current workspace':new Date(record.updated).toLocaleString();button.append(small);list.append(button)}if(!records.length)list.textContent='No saved workspaces yet.'}).catch(()=>{if(list.isConnected)list.textContent='Saved workspaces could not be read.'});if(!deviceDatabase)list.textContent='Device storage is unavailable.'}
async function workspaceIsOpen(id){if(!('BroadcastChannel'in window))return false;const probe=new BroadcastChannel('document-studio-tabs-v1'),token=uuid();let owned=false;probe.onmessage=e=>{if(e.data.kind==='owned'&&e.data.token===token)owned=true};probe.postMessage({kind:'probe',id,token});await new Promise(resolve=>setTimeout(resolve,250));probe.close();return owned}
async function openDeviceWorkspace(id){const sessionId=state.id,token=dialogVersion;try{await flushDeviceSave();await flushRecovery();const record=await deviceDatabase.get(id);if(!record?.state||record.ended)throw Error('This workspace is no longer available.');if(await workspaceIsOpen(id))throw Error('This workspace is open in another tab. Use that tab or close it first.');if(sessionId!==state.id||token!==dialogVersion||!$('dialog').open)return;stopRecovery();clearSessionUI();state=record.state;toolsError=hasToolDrafts(state.id)?'Unsaved PDF edits remain in this tab. Export a complete backup before closing.':'';deviceWriter=new DeviceWriter(deviceDatabase,record.revision);deviceDirty=false;deviceError='';close();openDoc(state.active);if(state.recoveryId)recoveryStatus('Recovery locked — unlock to resume');toast('Saved workspace opened.')}catch(error){toast(error.message)}}

let recoveryWriter=null,recoveryTimer=null,recoveryDirty=false,recoveryVersion=0,recoveryDatabase=null,recoveryLastSaved='';
function recoveryAvailable(){return !!(globalThis.crypto?.subtle&&globalThis.indexedDB)}
function recoveryStatus(message){$('recoveryStatus').textContent=message;$('storageMode').textContent=recoveryWriter?'Device + recovery':'Device storage'}
function scheduleRecovery(){if(!recoveryWriter)return;recoveryDirty=true;recoveryVersion++;recoveryStatus('Recovery: saving…');clearTimeout(recoveryTimer);recoveryTimer=setTimeout(()=>flushRecovery().catch(()=>{}),800)}
async function flushRecovery(){clearTimeout(recoveryTimer);return recoverySaveDrain.flush()}

const deviceSaveDrain=new SaveDrain({read:()=>({writer:deviceEnding?null:deviceWriter,dirty:deviceDirty,version:deviceVersion,value:state}),onSaved:version=>{if(version===deviceVersion){deviceDirty=false;deviceError='';dirty=false}renderSaveStatus()},onError:error=>{deviceError=error.message;renderSaveStatus()}});
const recoverySaveDrain=new SaveDrain({read:()=>({writer:recoveryWriter,dirty:recoveryDirty,version:recoveryVersion,value:state}),onSaved:version=>{recoveryLastSaved=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});if(version===recoveryVersion){recoveryDirty=false;recoveryStatus('Recovery saved '+recoveryLastSaved);$('recoveryWarning').hidden=true}},onError:error=>{recoveryDirty=true;recoveryStatus('Recovery not saved');$('recoveryWarning').hidden=false;$('recoveryWarningText').textContent=error.message}});
function completeRecoveryWriter(code,revision){return new RecoveryWriter(code,revision,recoveryDatabase,crypto,async id=>encodeRecoveryPDFs(await toolStore().list(id,{includeDrafts:true})),id=>collectOCRBackup(ocrDraftStore(),id))}
function stopRecovery(){clearTimeout(recoveryTimer);recoveryWriter=null;recoveryDirty=false;recoveryLastSaved='';$('recoveryWarning').hidden=true;recoveryStatus('Recovery off')}
function showAppearance(){const options=appearance.options();modal('Appearance',`<p>Personalize every interface theme. These settings stay on this browser and do not change your document files.</p><label for="uiTheme">Interface theme</label><select id="uiTheme"><option value="system">Match system</option><option value="white">White</option><option value="colored">Colored</option><option value="grey">Grey</option><option value="dark">Dark</option></select><label for="uiAccent">Accent color</label><input type="color" id="uiAccent" value="${options.accent}"><div class="accent-options">${[['Sage','#286453'],['Blue','#2855d4'],['Violet','#8550ca'],['Rose','#bb4269'],['Amber','#b16a16'],['Teal','#087b82']].map(([name,color])=>`<button aria-label="${name} accent" data-accent="${color}" aria-pressed="${options.accent===color}" style="background:${color}"></button>`).join('')}</div><label class="check"><input type="checkbox" id="darkPageView" ${options.darkPage?'checked':''}> Use a dark document page in Dark theme</label><p>Screen view only. Text colors adapt for viewing; images keep their colors. Printing, exports and opening the file elsewhere use the document’s original colors. This setting also works when System switches to Dark.</p><p id="appearanceStatus" role="status">Your choices are remembered after closing.</p>`);$('uiTheme').value=appearance.get();function status(saved){$('appearanceStatus').textContent=saved?'Appearance saved on this browser.':'Appearance changed for now, but browser storage is unavailable.'}function accent(value){$('uiAccent').value=value;status(appearance.setAccent(value));for(const button of document.querySelectorAll('[data-accent]'))button.setAttribute('aria-pressed',String(button.dataset.accent===value))}$('uiTheme').onchange=()=>status(appearance.set($('uiTheme').value));$('uiAccent').oninput=()=>accent($('uiAccent').value);$('darkPageView').onchange=()=>status(appearance.setDarkPage($('darkPageView').checked));for(const button of document.querySelectorAll('[data-accent]'))button.onclick=()=>accent(button.dataset.accent)}
function showRecovery(){if(!recoveryAvailable()){modal('Device recovery','<p>Encrypted recovery requires HTTPS, Web Crypto and IndexedDB. It is unavailable in this browser context. Export files to keep your work.</p>');return}recoveryDatabase??=recoveryStore();if(recoveryWriter){modal('Device recovery',`<p>Encrypted recovery is on for this workspace. ${recoveryLastSaved?'Last saved '+esc(recoveryLastSaved)+'.':''}</p><p>Keep your code private. It is needed again after reloading, returning, or ending a session. There is no password reset.</p><button class="wide" id="saveRecoveryNow">Save recovery now</button><button class="wide" id="showRecoveryCode">Show recovery code</button>`);action('saveRecoveryNow',async()=>{try{recoveryDirty=true;await flushRecovery();toast('Recovery saved on this browser.')}catch(error){toast(error.message)}});action('showRecoveryCode',()=>{let label=document.createElement('label');label.textContent='Recovery code';let field=document.createElement('textarea');field.readOnly=true;field.value=recoveryWriter.code;field.setAttribute('aria-label','Recovery code');$('dialogBody').append(label,field);field.select()});return}
 modal('Device recovery','<p>Keep a separate encrypted recovery copy of documents and saved PDFs on this browser. Ordinary device saves still reopen without a code. No documents or codes are sent to a server.</p><button class="wide" id="createRecovery">Enable recovery for this workspace</button><div class="panel-divider"></div><label for="recoveryCodeInput">Open an existing recovery copy</label><input id="recoveryCodeInput" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your DS1 recovery code"><label class="check"><input id="replaceRecoveryWorkspace" type="checkbox"> Replace this tab’s workspace with the recovered copy</label><button class="wide" id="resumeRecovery" hidden>Unlock recovery and keep this tab’s work</button><button class="primary" id="openRecovery">Replace with recovery copy</button><p>Export current work before replacing it. Recovery works only on the browser/profile where the copy was saved. Losing the code or clearing site data can make it unrecoverable.</p>');
 action('createRecovery',()=>{let code=createRecoveryCode();modal('Save your recovery code','<p>Save this code somewhere private before enabling recovery. Anyone with the code can unlock its copy on this browser. We cannot recover a lost code.</p><label for="newRecoveryCode">Recovery code</label><textarea id="newRecoveryCode" readonly></textarea><label class="check"><input type="checkbox" id="savedRecoveryCode"> I have saved this code somewhere private</label><button id="confirmRecovery" class="primary">Enable encrypted recovery</button>');$('newRecoveryCode').value=code;action('confirmRecovery',async()=>{if(!$('savedRecoveryCode').checked){toast('Save the recovery code and tick the checkbox first.');return}let sessionId=state.id,token=dialogVersion;const button=$('confirmRecovery');button.disabled=true;try{let writer=completeRecoveryWriter(code,0);await writer.save(state);if(sessionId!==state.id||token!==dialogVersion||!$('dialog').open)return;recoveryWriter=writer;state.recoveryId=parseRecoveryCode(code).id;recoveryLastSaved=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});recoveryStatus('Recovery enabled');close();scheduleRecovery();toast('Encrypted recovery enabled. Keep your code safe.')}catch(error){toast('Recovery could not be enabled: '+error.message);if(button.isConnected)button.disabled=false}})});
 async function openSavedRecovery(resume=false){if(!resume&&!$('replaceRecoveryWorkspace').checked){toast('Confirm replacing this tab’s workspace first.');return}const code=$('recoveryCodeInput').value.trim(),sessionId=state.id,token=dialogVersion;try{const {id}=parseRecoveryCode(code),record=await recoveryDatabase.get(id),payload=await openWorkspace(record,code);if(sessionId!==state.id||token!==dialogVersion||!$('dialog').open)return;if(!Array.isArray(payload.docs)||!payload.docs.length||payload.docs.length>MAX_DOCUMENTS||!Array.isArray(payload.trash)||payload.trash.length>200)throw Error('The recovery copy has an invalid workspace.');if(resume){if(id!==state.recoveryId)throw Error('Use the recovery code belonging to this tab’s workspace.');recoveryWriter=completeRecoveryWriter(code,record.revision);close();scheduleRecovery();toast('Recovery unlocked. This tab’s latest work was kept.');return}validateWorkspaceCounts(payload,{requireDocuments:true});let docs=payload.docs.map(importDoc),trash=payload.trash.map(importDoc);const restoredOCR=validateOCRBackup(payload.__recoveryOCR);const restoredPDFs=decodeRecoveryPDFs(payload.__recoveryPDFs);if(restoredPDFs.length){const {loadPDF,normalizePDFState}=await import('./src/pdf-model.mjs'),records=[];for(const item of restoredPDFs){const pdf=await loadPDF(item.bytes);records.push({...item,id:uuid(),workspace:sessionId,state:normalizePDFState(item.state,pdf.getPageCount())})}const existing=await toolStore().list(sessionId);if(existing.reduce((n,r)=>n+r.bytes.length,0)+records.reduce((n,r)=>n+r.bytes.length,0)>40000000)throw Error('Restored PDFs would exceed 40 MB. Export current PDFs and use an empty workspace.');if(sessionId!==state.id||token!==dialogVersion)return;await toolStore().putMany(records)}if(sessionId!==state.id||token!==dialogVersion)return;stopRecovery();clearSessionUI();state={...fresh(),id:state.id,docs,trash,snippets:(Array.isArray(payload.snippets)?payload.snippets:[]).slice(0,30).map(s=>({name:String(s.name||'Snippet').slice(0,80),text:String(s.text||'').slice(0,10000)})),templates:(Array.isArray(payload.templates)?payload.templates:[]).slice(0,20).map(t=>{const d=importDoc(t);return {title:d.title,content:d.content,layout:d.layout}}),recoveryId:id,active:docs[Math.max(0,payload.docs.findIndex(d=>d.id===payload.active))].id};recoveryWriter=completeRecoveryWriter(code,record.revision);close();openDoc(state.active);try{await restoreOCRBackup(ocrDraftStore(),sessionId,restoredOCR)}catch(error){toast('Documents/PDFs recovered; OCR draft not restored: '+error.message);return}toast('Workspace recovered from this browser.')}catch(error){toast('Could not recover: '+error.message)}}
 action('openRecovery',()=>openSavedRecovery(false));action('resumeRecovery',()=>openSavedRecovery(true));$('resumeRecovery').hidden=!/^[a-f0-9]{24}$/.test(state.recoveryId||'');
}
function showGettingStarted(){modal('Getting started','<p>Write and format in Continuous editing, then use File → Export document for a separate copy. Advanced layout, review and PDF tools are beta features; keep originals and inspect exported files.</p><p><strong>Documents save on this browser/profile.</strong> They do not sync to an account. Private browsing, clearing site data, device loss or browser eviction can remove them. Save warnings need attention before closing the tab.</p><p>File → Export workspace backup includes documents, history, PDFs and OCR drafts. Save the downloaded file, then restore through Open a file. Encrypted backups need their original password.</p><p>Moving from the original Site to GitHub Pages changes the address that owns browser storage. Export a complete backup at the old address and import it at the new address before removing the original.</p><button id="guideBackup" class="wide">Export workspace backup</button><button id="guideImport" class="wide">Open a document or backup</button><button id="guideStatus" class="wide">Check saving and offline status</button><p><a href="./help.html" target="_blank" rel="noopener">Read the full guide and known limits</a></p>');action('guideBackup',()=>{close();$('backup').click()});action('guideImport',()=>{close();$('import').click()});action('guideStatus',showAppStatus)}
function setupWelcome(){let seen=false;try{seen=localStorage.getItem('slate-forge.welcome.v1')==='1'}catch{}$('welcomeBanner').hidden=seen;$('openGettingStarted').onclick=showGettingStarted;$('dismissWelcome').onclick=()=>{$('welcomeBanner').hidden=true;try{localStorage.setItem('slate-forge.welcome.v1','1')}catch{}};if($('startupHelp'))$('startupHelp').hidden=true}
function wireDeviceFeatures(){setupWelcome();action('deviceStorage',showDeviceStorage);action('appearance',showAppearance);action('recovery',showRecovery);action('recoveryWarningOpen',showRecovery);addEventListener('pagehide',()=>{flushDeviceSave().catch(()=>{});flushRecovery().catch(()=>{})});document.addEventListener('visibilitychange',()=>{if(document.hidden){flushDeviceSave().catch(()=>{});flushRecovery().catch(()=>{})}});setupPWA()}
let installPrompt=null,pwaRegistration=null,offlineShellStatus='Checking…',offlinePreparing=false;
function handleShortcut(){const action=launchAction(location.search);if(!action)return;const url=new URL(location.href);url.searchParams.delete('action');history.replaceState(null,'',url);if(action==='new')showTemplates();if(action==='open')$('import').click();if(action==='storage')showDeviceStorage()}
function updateNetworkStatus(){const offline=navigator.onLine===false;$('connectionStatus').textContent=offline?'Offline':'On device';$('connectionStatus').dataset.offline=String(offline);$('connectionStatus').title=offline?'Offline — documents save on this device':'Documents save on this device; open app status'}
